import unittest
from unittest.mock import patch
from your_module import chemist_service, symptom_service, patient_service

class TestChemistLabScreen(unittest.TestCase):

    @patch('your_module.chemist_service.get_chemist')
    def test_query_chemist(self, mock_get_chemist):
        mock_get_chemist.return_value = {'chemist_id': 1, 'name': 'John Doe', 'address': '123 Main St', 'contact_details': '123-456-7890'}
        result = chemist_service.get_chemist(1)
        self.assertEqual(result, {'chemist_id': 1, 'name': 'John Doe', 'address': '123 Main St', 'contact_details': '123-456-7890'})

    @patch('your_module.chemist_service.get_chemist')
    def test_query_non_existent_chemist(self, mock_get_chemist):
        mock_get_chemist.return_value = None
        result = chemist_service.get_chemist(1)
        self.assertIsNone(result)

    @patch('your_module.chemist_service.delete_chemist')
    def test_delete_chemist(self, mock_delete_chemist):
        mock_delete_chemist.return_value = True
        result = chemist_service.delete_chemist(1)
        self.assertTrue(result)

    @patch('your_module.chemist_service.delete_chemist')
    def test_delete_chemist_with_open_prescriptions(self, mock_delete_chemist):
        mock_delete_chemist.return_value = False
        result = chemist_service.delete_chemist(1)
        self.assertFalse(result)

    @patch('your_module.symptom_service.get_symptom')
    def test_query_symptom(self, mock_get_symptom):
        mock_get_symptom.return_value = {'symptom_code': 'S001', 'description': 'Symptom 1'}
        result = symptom_service.get_symptom('S001')
        self.assertEqual(result, {'symptom_code': 'S001', 'description': 'Symptom 1'})

    @patch('your_module.patient_service.get_patient')
    def test_view_appointment_request(self, mock_get_patient):
        mock_get_patient.return_value = {'patient_id': 1, 'name': 'John Doe', 'age': 30, 'sex': 'M', 'address': '123 Main St', 'contact_details': '123-456-7890'}
        result = patient_service.get_patient(1)
        self.assertEqual(result, {'patient_id': 1, 'name': 'John Doe', 'age': 30, 'sex': 'M', 'address': '123 Main St', 'contact_details': '123-456-7890'})

